mapper.select:
SELECT p.PAYMENTIDX as "paymentIdx", p.MERCHANTUID as "merchantUid", u.USERID as "userId", u.NICKNAME as "nickname", p.PAYMETHOD as "payMethod", p.CHARGEAMOUNT as "chargeAmount", TO_CHAR(p.PAIDAT, 'YYYY-MM-DD HH24:MI') as "paidAt", p.PAYSTATUS as "payStatus" FROM PAYMENT p JOIN USERS u ON p.USERIDX = u.USERIDX
AND p.PAYSTATUS = #{status}
ORDER BY p.PAIDAT DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY
